UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = 'Le Grand-Duc régnant, d''après sa fiche officielle sur monarchie.lu, avec la date et le lieu de naissance.', l.gaps = NULL WHERE p.dataset_name = 'lu_pep_grand_duke' AND c.code = 'LU-a' AND f.label LIKE 'Grand-Duc%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = 'Les 15 membres du gouvernement en fonction, d''après gouvernement.lu.', l.gaps = 'La fonction exacte (Premier ministre, ministre de…, secrétaire d''État) n''est pas lue : tous sont « membre du gouvernement ». Ni date de naissance ni date d''entrée en fonction sur la page.' WHERE p.dataset_name = 'lu_pep_government' AND c.code = 'LU-a' AND f.label LIKE 'Membre du gouvernement%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = '34 anciens membres du gouvernement et le détail de leurs mandats, d''après la page officielle des anciens membres (gouvernement.lu).', l.gaps = NULL WHERE p.dataset_name = 'lu_pep_government_former' AND c.code = 'LU-a' AND f.label LIKE 'Ancien membre%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = 'Bourgmestre et échevins de la Ville de Luxembourg, d''après le fichier des collèges des bourgmestre et échevins (ministère des Affaires intérieures, data.public.lu).', l.gaps = 'Pas de date de naissance : l''ID repose sur le nom, le prénom et la commune.' WHERE p.dataset_name = 'lu_pep_municipal' AND c.code = 'LU-AMLR';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = 'Les 60 députés en fonction, d''après l''open data de la Chambre des Députés (data.public.lu), avec la date de naissance.', l.gaps = NULL WHERE p.dataset_name = 'lu_pep_chamber' AND c.code = 'LU-b' AND f.label LIKE 'Député%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = '58 anciens députés dont le mandat a pris fin il y a moins de 5 ans, d''après la liste officielle des anciens députés (depuis 1999).', l.gaps = 'La date de naissance manque pour certains anciens députés : leur ID repose alors sur le nom et le prénom.' WHERE p.dataset_name = 'lu_pep_chamber_former' AND c.code = 'LU-b' AND f.label LIKE 'Ancien député%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = '35 membres du Conseil d''État en fonction ou sortis depuis moins de 5 ans, d''après la liste officielle des membres depuis 1857 (conseil-etat.public.lu).', l.gaps = NULL WHERE p.dataset_name = 'lu_pep_council_of_state' AND c.code = 'LU-b' AND f.label LIKE 'Membre du Conseil d''État%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = 'Nominations, renouvellements et démissions publiés au Journal officiel (Legilux) depuis 2017, avec les anciens titulaires.', l.gaps = 'Titulaires nommés avant 2017 absents, sauf renouvellement ou démission depuis. Ni identifiant ni date de naissance dans les actes. Quelques actes à la tournure non reconnue sont cités dans le message de l''exécution.' WHERE p.dataset_name = 'lu_pep_legilux' AND c.code = 'LU-b' AND f.label LIKE 'Membre du Conseil d''État%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = '10 dirigeants des partis représentés à la Chambre des Députés.', l.gaps = 'Pas de liste officielle des dirigeants (un site par parti) : les autres membres des organes dirigeants (comités directeurs, bureaux exécutifs) ne sont pas lus.' WHERE p.dataset_name = 'lu_pep_political_parties' AND c.code = 'LU-c';
