UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = '8 anciens députés européens élus au Luxembourg, sortis depuis moins de 5 ans, d''après l''API open data du Parlement européen.', l.gaps = NULL WHERE p.dataset_name = 'lu_pep_europarl_former' AND c.code = 'LU-EU' AND f.label LIKE 'Député au Parlement%';
UPDATE pep_function_parser l JOIN parser p ON p.id = l.parser_id JOIN pep_function f ON f.id = l.function_id JOIN pep_category c ON c.id = f.category_id SET l.covered_scope = 'Le membre luxembourgeois de la Commission en fonction (collège des commissaires) et l''ancien commissaire sorti depuis moins de 5 ans.', l.gaps = 'L''ancien commissaire est lu sur une page donnée en paramètre (formerCommissionerPages) : à mettre à jour à chaque changement de commissaire.' WHERE p.dataset_name = 'lu_pep_eu_commission' AND c.code = 'LU-EU' AND f.label LIKE 'Membre luxembourgeois%';
